{"query":"
SELECT event_type, COUNT(*) as count 
FROM events 
GROUP BY event_type 
ORDER BY count DESC;
"}

{"query":"
-- Estimate current fraud loss rate
SELECT 
  ROUND(100.0 * SUM(CASE WHEN event_type = 'refund' THEN amount_usd ELSE 0 END) / SUM(CASE WHEN event_type = 'purchase_attempt' AND status = 'success' THEN amount_usd ELSE 0 END), 2) as fraud_loss_rate_pct
FROM events;
"}
